-- Optional Supabase persistence schema. -- Enable Row Level Security and use Supabase Auth before storing real personal data. create table if not exists public.debt_profiles (   user_id uuid primary key references auth.users(id) on delete cascade,   monthly_income numeric not null default 0,   monthly_expenses numeric not null default 0,   extra_payment numeric not null default 0,   updated_at timestamptz not null default now() );  create table if not exists public.debts (   id uuid primary key default gen_random_uuid(),   user_id uuid not null references auth.users(id) on delete cascade,   name text not null,   creditor text,   type text,   balance numeric not null default 0 check (balance >= 0),   annual_rate numeric not null default 0 check (annual_rate >= 0),   minimum_payment numeric not null default 0 check (minimum_payment >= 0),   due_day int not null default 1 check (due_day between 1 and 31),   secured boolean not null default false,   notes text,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  alter table public.debt_profiles enable row level security; alter table public.debts enable row level security;  create policy "Users manage own debt profile" on public.debt_profiles for all using (auth.uid() = user_id) with check (auth.uid() = user_id);  create policy "Users manage own debts" on public.debts for all using (auth.uid() = user_id) with check (auth.uid() = user_id);